def process_payment(account_id: str, amount: float, currency: str = "USD") -> dict:
    """Process payment transaction with verification and risk check."""
    # Verify account and positive amount
    assert len(account_id) > 0, "Invalid account id"
    assert amount > 0.0, "Amount must be positive"

    # Check fraud risk score
    if amount > 10000.0:
        risk_flag = True
    else:
        risk_flag = False

    return {"account_id": account_id, "amount": amount, "risk_flag": risk_flag}

